package top.pxczxn.community.web.sanction;
import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RestController; import top.pxczxn.community.sanction.application.CommunitySanctionService; import top.pxczxn.community.sanction.application.SanctionView; import top.pxczxn.community.shared.auth.CommunityAuth; import top.pxczxn.platform.common.result.Result; import java.util.List;
@RestController @RequiredArgsConstructor @RequestMapping("/api/v1/sanctions") public class CommunitySanctionController { private final CommunitySanctionService service; private final CommunityAuth auth; @GetMapping("/me") public Result<List<Response>> mine(){return Result.ok(service.mine(auth.getLoginUserId()).stream().map(Response::from).toList());} public record Response(String id,String type,String reasonCode,String reasonNote,String status,String expiresAt){static Response from(SanctionView v){return new Response(v.id().toString(),v.sanctionType(),v.reasonCode(),v.reasonNote(),v.status(),v.expiresAt()==null?null:v.expiresAt().toString());}} }
